param([ValidateSet('01','02','03')][string]$RunId='01')
$ErrorActionPreference='Stop';$root=[IO.Path]::GetFullPath((Join-Path $PSScriptRoot '../..'));$private=Join-Path $root 'server/.local/p27c';$path=Join-Path $private "uat-$RunId-server.json";$record=Get-Content -LiteralPath $path -Raw|ConvertFrom-Json;$port=3106+[int]$RunId
if($record.schema -ne "upms_test_p27c_uat_20261023_$RunId"){throw 'UAT schema identity mismatch'};$process=Get-Process -Id $record.serverPid -ErrorAction Stop;$native=Get-CimInstance Win32_Process -Filter "ProcessId=$($record.serverPid)";if($process.StartTime.ToUniversalTime().Ticks -ne [long]$record.startTicks -or $native.ParentProcessId -ne $record.launcherPid -or $native.CommandLine -notmatch 'server[\/]tools[\/]uat-serve\.mjs' -or (Get-NetTCPConnection -State Listen -LocalPort $port).OwningProcess -ne $process.Id){throw 'UAT process identity mismatch; nothing stopped'}
$stamp=[DateTime]::UtcNow.Ticks;Copy-Item -LiteralPath $path -Destination (Join-Path $private "uat-$RunId-server-stopped-$stamp.json");foreach($stream in @('stdout','stderr')){$log=Join-Path $private "uat-$RunId-server.$stream.log";if(Test-Path -LiteralPath $log){Copy-Item -LiteralPath $log -Destination (Join-Path $private "uat-$RunId-server-$stamp.$stream.log")}}
Stop-Process -Id $process.Id;$process.WaitForExit(10000)|Out-Null;if(Get-NetTCPConnection -State Listen -LocalPort $port -ErrorAction SilentlyContinue){throw 'UAT port still busy; preserve record'};Remove-Item -LiteralPath $path;Write-Output "Stopped only verified DEMO UAT generation $RunId. Database, credentials and scenario data preserved."
